#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Frozen kit guide. Human performs every UI action.
SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)
KIT=""
PYTHON=/usr/bin/python3
CANDIDATE=""
COLLECTOR=""
RUN=""
COLLECTOR_PID=""
INVOCATION=""
export PYTHONDONTWRITEBYTECODE=1 PYTHONNOUSERSITE=1
export PYTHONPATH=""
umask 077

collect() { "$PYTHON" "$COLLECTOR" "$@"; }
guide() { "$PYTHON" "$SCRIPT_DIR/desktop_qualification_guide.py" "$KIT" "$@"; }

cleanup() {
  local rc=$? count=0
  trap - EXIT INT TERM
  if [[ -n "$COLLECTOR_PID" ]] && kill -0 "$COLLECTOR_PID" 2>/dev/null; then
    [[ -z "$RUN" ]] || collect cancel "$RUN" >> "$INVOCATION/control.log" 2>&1 || true
    say "Waiting for the collector to stop its owned launch and retain evidence."
    while kill -0 "$COLLECTOR_PID" 2>/dev/null && (( count < 240 )); do
      sleep 1
      count=$((count+1))
    done
    if kill -0 "$COLLECTOR_PID" 2>/dev/null; then
      warn "Collector is still running. Do not relaunch; tell the agent."
      say "Private logs: $INVOCATION"
      exit 1
    fi
    wait "$COLLECTOR_PID" 2>/dev/null || true
  fi
  if [[ -n "$RUN" ]]; then
    if [[ -f "$RUN/history-before.json" && ! -f "$RUN/history-after.json" ]]; then
      guide history-after "$RUN" || { warn "History verification incomplete; retain $RUN"; rc=1; }
    fi
    guide summarize "$RUN" || { warn "Evidence copy incomplete; retain original $RUN"; rc=1; }
    say "Original private evidence: $RUN"
  fi
  [[ -z "$INVOCATION" ]] || say "Durable guide logs: $INVOCATION"
  if (( rc )); then warn "Attempt stopped. Do not retry yet; send the agent the paths above."
  else say "Collection ended. Tell the agent done for independent review."; fi
  exit "$rc"
}

observation() {
  local result
  result=$(guide observe "$RUN" "$COLLECTOR_PID" "$2 [p/f/u]:")
  collect observe "$RUN" --criterion "$1" --operator maintainer --method human --outcome "$result"
}

run_wizard() {
  TOTAL_STAGES=5
  if [[ $# -lt 2 || "$1" != "--kit" ]]; then
    warn "Usage: bash desktop_qualification_operator.sh --kit PRIVATE_KIT [--check]"
    return 2
  fi
  KIT=$(cd -- "$2" && pwd -P)
  shift 2
  COLLECTOR=$(guide field collector)
  MODEL=$(guide field model)
  GUARDIAN=$(guide field guardian)
  REVISION=$(guide field source_revision)
  DURABLE=$(guide field durable_root)
  if [[ "${1:-}" == "--check" && $# == 1 ]]; then
    guide check >/dev/null
    collect freeze --help >/dev/null
    say "Pinned assets and collector imports verified. No launch, network request, or inference."
    return
  fi
  if (( $# )); then warn "Usage: bash run-clean-exit.sh [--check]"; return 2; fi
  [[ -t 0 ]] || { warn "Run this guide in an interactive Terminal."; return 2; }
  local runtime
  runtime=$(guide check)

  stage "Prepare host Desktop"
  say "One clean-exit check on this Mac; candidate $REVISION. No VM."
  say "Paid $MODEL; $GUARDIAN Guardian; Lightning naming."
  say "These are explicit selections for this attempt, not model-specific qualification requirements."
  say "Catalog changes are recorded as provenance; integration and preservation checks still apply."
  say "Workspace setup happens before the baseline. Then 10 minutes from candidate launch, including observations; $(guide field requests) requests, $(guide field output_tokens) output tokens/request."
  say "One attempt only. No retries or model substitutions. Ctrl-C cancels and retains evidence."
  step "Save Desktop work. Note your current account, installed plugins and Code Review availability, then QUIT ChatGPT Desktop normally."
  note "Keep ordinary settings unchanged. No password, token, account name, or other secret is requested."
  confirm "Desktop is quit and you are ready to do the check now?" || { say "No launch performed."; return; }

  mkdir -p "$DURABLE/invocations"
  INVOCATION=$(mktemp -d "$DURABLE/invocations/guide.XXXXXX")
  trap cleanup EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  guide receipt "$INVOCATION"
  say "Allocating one fresh workspace. The preservation baseline is captured after ordinary-client setup."
  if guide prepare \
    > "$INVOCATION/prepare.json" 2> "$INVOCATION/prepare.log"; then
    :
  else
    warn "Preparation failed before launch. Private diagnostic: $INVOCATION/prepare.log" >&2
    return 1
  fi
  RUN=$("$PYTHON" -c 'import json,sys; print(json.load(open(sys.argv[1]))["run"])' "$INVOCATION/prepare.json")
  stage "Set up the fresh workspace before the baseline"
  step "Open ordinary ChatGPT Desktop yourself. In Codex mode, add/select this exact folder and start a NEW empty conversation within it."
  printf '\n%s\n\n' "$RUN/workspace"
  say "Complete the workspace trust prompt if shown. Do not send a message or change other settings."
  step "Quit ordinary Desktop fully with Cmd-Q. This folder will be reused for the candidate check; earlier run folders are different."
  confirm "The exact workspace is selected, setup is complete, and ordinary Desktop is quit?" || { say "Stopped before baseline and candidate launch."; return 1; }
  if collect freeze "$RUN" > "$INVOCATION/freeze.json" 2> "$INVOCATION/freeze.log"; then
    :
  else
    warn "Baseline capture failed before launch. Private diagnostic: $INVOCATION/freeze.log" >&2
    return 1
  fi
  say "Recording hashes of existing session-history bytes; new turns may append without changing those bytes."
  guide history-before "$RUN"
  collect run "$RUN" > "$INVOCATION/collector.log" 2>&1 &
  COLLECTOR_PID=$!
  guide ready "$RUN" "$COLLECTOR_PID"

  stage "Check preserved account and features"
  say "The candidate's native process and launch receipt were observed."
  say "Keep $MODEL selected throughout this check. Selecting another main model ends this bounded attempt; model switching is a separate test."
  say "p = personally verified; f = missing/changed/failed; u = not observed or unsure."
  step "Open Settings → Account and check the account matches what you used before. Do not sign in again or change settings."
  observation account-visible "Account still visible and correct"
  step "Inspect the installed plugins and their enabled state against your ordinary Desktop. Do not toggle them."
  observation plugins-visible "Expected plugins visible with the same enabled state"
  step "Check Code Review is still offered as before. Do not start a review or inference just to check. If availability is unclear, use u."
  observation code-review-eligible "Code Review remains available"

  stage "Submit the fixed smoke prompt"
  say "In Codex mode, select the EXACT workspace prepared above and start a NEW conversation within it."
  printf '\n%s\n\n' "$RUN/workspace"
  say "Select $MODEL. Submit exactly this one prompt:"
  printf '\n%s\n\n' 'Reply exactly: tofa-clean-exit-ok. Do not use tools or create files.'
  say "Prompt file: $RUN/prompt.txt"
  step "Wait for the main answer. Inspect the automatic title separately; do not wait on a visibly failed title."
  say "Do not send follow-ups, switch models, rename the thread, or resume an old conversation."
  guide input "$RUN" "$COLLECTOR_PID" 'Press Enter after the main answer finishes or fails.' >/dev/null
  observation smoke-response "Main answer was exactly tofa-clean-exit-ok with no tool execution"
  observation title-visible "A descriptive automatic title appeared"

  stage "Quit normally and retain evidence"
  step "Quit ChatGPT Desktop normally using its Quit command (Cmd-Q). Closing a window alone is insufficient."
  guide input "$RUN" "$COLLECTOR_PID" 'Press Enter once Desktop has quit.' >/dev/null
  say "Checking that this attempt's native and launcher processes exited without a forced stop."
  guide exited "$RUN" "$COLLECTOR_PID"
  collect finish "$RUN"
  say "Collecting the after-snapshot and checking the expired route; this may take a few minutes."
  wait "$COLLECTOR_PID"
  COLLECTOR_PID=""
  # EXIT trap emits a non-qualifying summary and saves a durable private copy.
}

run_wizard "$@"; exit
